import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The algebra of the neuron","description":"","frontmatter":{},"headers":[],"params":{"slug":"neuro","address":"ae0887b2-82e0-82d5-bd5b-acf8d7a5e25d","receipt":"daa1817a-5cf6-8438-9b66-c5383689ae28"},"relativePath":"docs/publications/neuro.md","filePath":"docs/publications/[slug].md"}`),a={name:`docs/publications/neuro.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-algebra-of-the-neuron" tabindex="-1">The algebra of the neuron <a class="header-anchor" href="#the-algebra-of-the-neuron" aria-label="Permalink to “The algebra of the neuron”">​</a></h1><blockquote><p>neuroscience, demarcated — all-or-none firing as a threshold step, sub-threshold silence, supra-threshold spike, monotone firing, spatial summation (two sub-threshold inputs sum to fire), the excitatory−inhibitory net drive, the −70→+40 mV action potential (rest &lt; threshold &lt; peak), Hebbian coincidence (Δw = pre·post), and the refractory cap — the textbook model as decidable algebra, not clinical and not about any individual</p></blockquote><p>These 9 facts hold by decision. Each was proven in Lean 4 — no Mathlib, checked sorry-free — and every sentence below links the proof that seals it. This note claims nothing beyond what its theorems settle: not that the domain is complete, only that the prose says nothing the proofs do not. It was written by reading the sealed ledger; read the proofs, not the prose.</p><h2 id="the-facts-each-backed-by-its-proof" tabindex="-1">The facts, each backed by its proof <a class="header-anchor" href="#the-facts-each-backed-by-its-proof" aria-label="Permalink to “The facts, each backed by its proof”">​</a></h2><ul><li>The all-or-none law: the neuron&#39;s output is binary — 0 or 1 — for every input; there is no partial spike. — <a href="/theorem/all_or_none">proof</a>.</li><li>Below threshold, silence: an input under the threshold (here 5) produces no spike — output 0. — <a href="/theorem/subthreshold_silent">proof</a>.</li><li>At or above threshold, a spike: an input meeting the threshold fires — output 1. — <a href="/theorem/suprathreshold_fires">proof</a>.</li><li>Firing is monotone in input: more depolarisation never un-fires a neuron — the step never steps down. — <a href="/theorem/firing_monotone">proof</a>.</li><li>Spatial summation: two sub-threshold inputs (3 and 3, each silent alone at threshold 5) SUM to a supra-threshold 6 and fire — the whole exceeds either part. — <a href="/theorem/spatial_summation">proof</a>.</li><li>The net drive is excitatory minus inhibitory: 3 EPSPs − 1 IPSP = 2 (net excitation), while 3 − 3 = 0 — balanced inhibition cancels excitation exactly (a reflection through zero, like acid–base through 7). — <a href="/theorem/excitatory_inhibitory_net">proof</a>.</li><li>The action potential swings from rest −70 mV to peak +40 mV — a 110 mV excursion — with the −55 mV threshold strictly between: rest &lt; threshold &lt; peak. — <a href="/theorem/action_potential_swing">proof</a>.</li><li>&quot;Fire together, wire together&quot;: the Hebbian weight change Δw = pre·post is 1 exactly when BOTH the pre- and post-synaptic neurons fire — coincidence detection, an AND. — <a href="/theorem/hebbian_coincidence">proof</a>.</li><li>The absolute refractory period caps firing: a supra-threshold input (9 ≥ 5) arriving within the refractory window (t = 1 &lt; 2) produces NO second spike — one spike per window, a finite dead time, never a runaway. — <a href="/theorem/refractory_caps_spike">proof</a>.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to “Provenance”">​</a></h2><p>These 9 proofs fold, order-invariant, to the receipt <code>daa1817a-5cf6-8438-9b66-c5383689ae28</code> — recompute it from the same ledger and it returns. The note itself content-addresses to a uuid, so any edit is visible. Writing descends from reading: this note holds only what the proofs it links already sealed, and it was audited by uuidna&#39;s own honesty gate before it was published — a sentence that overreached a proof would have been refused, not shipped.</p><p>Source · <a href="https://github.com/uuidna/uuidna/blob/main/lean/Neuro.lean" target="_blank" rel="noreferrer">lean/Neuro.lean</a> · <a href="/theorems">all theorems</a></p><hr><p><strong>Audited before published</strong> · this note passed uuidna&#39;s honesty gate at build time — every claim above links the proof that seals it. Content-address <code>ae0887b2</code> · proofs fold to receipt <code>daa1817a</code> (the handles; the full uuids are in this page&#39;s meta, recomputable) · 9 sealed theorems.</p><p><a href="/publications">All publications</a> · <a href="/theorems">All theorems</a> · <a href="/trials">How auditing works</a></p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};